#!/usr/bin/env python3
"""Turns the DINOBYTE sheet (assets/fonts/dbyte_1x.png, 16x16 cells of 6x8) into odin/game/font_data.odin.

Each row of a glyph is a u8 bit mask, bit x = pixel in column x. Any pixel with alpha > 0 is ink.
"""
import os
from PIL import Image

root = os.path.join(os.path.dirname(__file__), "..")
sheet = Image.open(os.path.join(root, "assets", "fonts", "dbyte_1x.png")).convert("RGBA")
W, H = 6, 8
assert sheet.size == (16 * W, 16 * H)

lines = [
    "// Generated by tools/gen_font.py from assets/fonts/dbyte_1x.png (DINOBYTE by mby, CC BY 4.0). Do not edit.",
    "package game",
    "",
    f"FONT_WIDTH :: {W}",
    f"FONT_HEIGHT :: {H}",
    "",
    f"FONT_GLYPHS := [256][FONT_HEIGHT]u8 {{",
]
for code in range(256):
    cx, cy = (code % 16) * W, (code // 16) * H
    rows = []
    for y in range(H):
        bits = 0
        for x in range(W):
            if sheet.getpixel((cx + x, cy + y))[3] > 0:
                bits |= 1 << x
        rows.append(bits)
    lines.append("\t{" + ", ".join(str(v) for v in rows) + "},")
lines.append("}")
with open(os.path.join(root, "odin", "game", "font_data.odin"), "w") as f:
    f.write("\n".join(lines) + "\n")
